read=lambda n:json.loads((B/(n+'.json')).read_text());reports={n:read(n)for n in ['physics-tests','item-tests','world-tests','browser-tests','offline-tests','unchanged-renders','scope-tests','comparison-report','release-smoke','render-mechanics-tests','mechanics-tests','rescue-browser-tests','grand-prix-tests','grand-prix-browser-tests']}
