raw=H.read_bytes();sha=lambda x:hashlib.sha256(x).hexdigest();metrics=read('asset-metrics');assert sha(raw)==metrics['html_sha256'];assert reports['release-smoke']['html_sha256']==sha(raw);assert raw==Path('/tmp/blokraya-6h/candidate.html').read_bytes()
